(()=>{const e=document.getElementById("root");if(e)e.outerHTML="<div id=\"front\" class=\"wrap\">\r\n  <div id=\"adminPreviewBar\" class=\"adminPreviewBar\"><div><strong>管理員預覽模式</strong><small id=\"previewAdminUser\"></small></div><div class=\"btns\"><button class=\"btn primary\" onclick=\"returnToAdmin()\">返回管理後台</button><button class=\"btn\" onclick=\"logout()\">登出</button></div></div>\r\n  <div class=\"top\">\r\n    <div class=\"brand\"><div id=\"secretLogo\" class=\"logo\" onclick=\"secretAdminTap()\" aria-label=\"公司Logo\"><img src=\"../assets/company-logo.png\" alt=\"公司Logo\"></div><div><h1>活動調查系統</h1><p>Department Dining Survey</p></div></div>\n    <div id=\"frontStatus\" class=\"pill\">載入中</div>\r\n  </div>\r\n  <div id=\"setup\" class=\"setup\">尚未填入 Firebase 設定。請在 HTML 裡找到 <b>firebaseConfig</b>，填入你的 Firebase Web App 設定。</div>\r\n  <div id=\"frontLoading\" class=\"card frontLoading\">正在讀取問卷設定...</div>\r\n  <div id=\"frontContent\" style=\"display:none\">\r\n    <section class=\"hero\"><h2 id=\"surveyTitle\"></h2><p id=\"surveyDesc\"></p><div id=\"deadline\" class=\"deadline\"></div></section>\r\n    <div id=\"finalFront\" class=\"final\" style=\"display:none\"></div>\r\n    <div id=\"closed\" class=\"closed\" style=\"display:none\">本次調查目前未開放或已截止，感謝大家。</div>\r\n    <div id=\"done\" class=\"card success\" style=\"display:none\"></div>\r\n    <div id=\"formGrid\" class=\"grid\">\r\n      <section class=\"card\"><h3>填寫問卷</h3>\r\n        <div class=\"field\"><label for=\"dept\">部門<span class=\"required\">*</span></label><select id=\"dept\" required><option value=\"\">請選擇部門</option></select></div>\r\n        <div class=\"field\"><label for=\"member\">姓名<span class=\"required\">*</span></label><select id=\"member\" required disabled><option value=\"\">請先選擇部門</option></select></div>\r\n        <div class=\"field attendanceModeField\"><label>參加狀態<span class=\"required\">*</span></label><div class=\"attendanceModeGroup\"><label class=\"attendanceModeChoice attend\"><input type=\"radio\" name=\"attendanceMode\" id=\"attendYes\" value=\"attend\"><span><b>可以參加</b><small>繼續選擇可配合的日期</small></span></label><label class=\"attendanceModeChoice cannot\"><input type=\"radio\" name=\"attendanceMode\" id=\"cannot\" value=\"cannot\"><span><b>不克參加</b><small>所有候選日期皆無法參加</small></span></label></div></div>\r\n        <div id=\"attendanceDateSection\" class=\"field\"><label>可參加日期（可複選）<span class=\"required\">*</span></label><div id=\"dateBox\" class=\"dateAvailabilityBox\"></div></div>\r\n        <div id=\"rankSection\" class=\"field\"><label>餐廳選擇順序</label><div id=\"rankGrid\" class=\"rankGrid\"></div></div>\r\n        <div class=\"field\"><label for=\"note\">備註（選填）</label><textarea id=\"note\" maxlength=\"500\"></textarea></div>\r\n        <div class=\"btns\"><button id=\"submitBtn\" class=\"btn primary\" onclick=\"submitVote()\">確認並送出</button><button class=\"btn\" onclick=\"resetVoteForm()\">清除內容</button></div><div id=\"submitStatus\" class=\"submitStatus\" role=\"status\" aria-live=\"polite\"></div>\r\n      </section>\r\n      <aside class=\"card\"><div id=\"frontInstructionsSection\" hidden><h3>填寫說明</h3><div id=\"editPolicyNotice\" class=\"notice\"></div><br></div><h3>餐廳資訊</h3><div id=\"restInfo\" class=\"restaurants\"></div></aside>\r\n    </div>\r\n  </div>\r\n</div>\r\n<div id=\"loginMask\" class=\"modalMask\">\n  <div class=\"manageLoginVisual\" aria-hidden=\"true\">\n    <div class=\"manageVisualGlow\"></div>\n    <div class=\"manageVisualCard manageVisualForm\"><span></span><i></i><i></i><i></i></div>\n    <div class=\"manageVisualCard manageVisualCalendar\"><b></b><b></b><b></b><b></b></div>\n    <div class=\"manageVisualCard manageVisualPeople\"><i></i><i></i><i></i></div>\n  </div>\n  <div class=\"modal loginDialog\">\n    <div class=\"modalHead loginBrand\"><img src=\"../assets/company-logo.png\" alt=\"環興科技股份有限公司\"></div>\n    <div class=\"manageLoginDivider\" aria-hidden=\"true\"></div>\n    <h1 class=\"manageLoginTitle\">部門聚餐調查系統</h1>\n    <p class=\"manageLoginSubtitle\">聚餐規劃、意願調查與結果彙整</p>\n    <div class=\"loginActions\"><button id=\"loginBtn\" class=\"btn primary loginPrimary\" onclick=\"loginGoogle()\">使用 Google 帳號登入</button><button class=\"loginCancel\" onclick=\"closeLogin()\">取消</button></div>\n    <p id=\"loginMsg\" class=\"loginMessage\" role=\"status\" aria-live=\"polite\"></p>\n  </div>\n</div>\n<div id=\"responseEditMask\" class=\"modalMask responseEditMask\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"responseEditTitle\"><div class=\"modal responseEditDialog\"><div class=\"responseEditHead\"><div><h2 id=\"responseEditTitle\">編輯同仁問卷</h2><p id=\"responseEditIdentity\"></p></div><button class=\"responseEditClose\" type=\"button\" onclick=\"closeResponseEditor()\" aria-label=\"關閉\">×</button></div><div class=\"responseEditBody\"><label class=\"responseCannotChoice\"><input id=\"responseEditCannot\" type=\"checkbox\" onchange=\"updateResponseEditorAvailability()\"><span><b>不克參加</b><small>勾選後會清除日期與餐廳選擇</small></span></label><div class=\"field\"><label>可參加日期（可複選）<span class=\"required\">*</span></label><div id=\"responseEditDates\" class=\"responseEditDates\"></div></div><div class=\"field\"><label>餐廳選擇順序</label><div id=\"responseEditRanks\" class=\"responseEditRanks\"></div></div><div class=\"field\"><label for=\"responseEditNote\">備註（選填）</label><textarea id=\"responseEditNote\" maxlength=\"500\"></textarea></div><div id=\"responseEditStatus\" class=\"submitStatus\" role=\"status\" aria-live=\"polite\"></div></div><div class=\"responseEditActions\"><button class=\"btn\" type=\"button\" onclick=\"closeResponseEditor()\">取消</button><button id=\"responseEditSaveBtn\" class=\"btn primary\" type=\"button\" onclick=\"saveResponseEdit()\">儲存修改</button></div></div></div>\r\n<div id=\"toast\" class=\"toast\"></div>\r\n<div id=\"admin\" class=\"admin\"><div class=\"layout\"><aside class=\"side\"><div class=\"ab\"><img src=\"../assets/company-logo.png\"><div><h2>部門聚餐管理</h2><small id=\"adminUser\"></small><small id=\"adminRole\" class=\"accessRole\"></small></div></div><button class=\"nav active\" data-access=\"all\" onclick=\"panel('dash',this)\">儀表板</button><button class=\"nav\" data-access=\"all\" onclick=\"panel('surveyP',this)\">活動管理</button><button class=\"nav\" data-access=\"manager\" onclick=\"panel('memP',this)\">人員設定</button><button class=\"nav\" data-access=\"manager\" onclick=\"panel('dateP',this)\">日期管理</button><button class=\"nav\" data-access=\"manager\" onclick=\"panel('restP',this)\">餐廳管理</button><button class=\"nav\" data-access=\"manager\" onclick=\"panel('costP',this)\">費用試算</button><button class=\"nav\" data-access=\"all\" onclick=\"panel('respP',this)\">投票結果</button><button class=\"nav\" data-access=\"manager\" onclick=\"panel('mailP',this)\">信件通知</button><button class=\"nav\" data-access=\"manager\" onclick=\"panel('finalP',this)\">最終決議</button><button class=\"nav\" data-access=\"system\" onclick=\"panel('sysMemP',this)\">人員管理</button><button class=\"nav\" data-access=\"manager\" onclick=\"panel('accessP',this)\">權限管理</button><button class=\"nav\" data-access=\"system\" onclick=\"panel('frontProtectP',this)\">前台防護</button><button class=\"nav\" data-access=\"system\" onclick=\"panel('featureSettingsP',this)\">功能設定</button><button class=\"nav\" data-access=\"all\" onclick=\"exportExcel()\">Excel 匯出</button><button class=\"nav\" data-access=\"all\" onclick=\"logout()\">登出</button></aside><main class=\"main\"><div class=\"head\"><h1 id=\"adminTitle\">儀表板</h1><div class=\"btns\" style=\"margin:0\"><select id=\"activeSurveySelect\" onchange=\"setActiveSurvey(this.value)\"></select><button class=\"btn\" onclick=\"copyAdminLink()\">複製活動管理網址</button><button class=\"btn\" onclick=\"showFront()\">預覽問卷</button></div></div>\n<section id=\"dash\" class=\"panel active\"><div class=\"stats\"><div class=\"stat\"><b id=\"sFilled\">0</b><span>已填人數</span></div><div class=\"stat\"><b id=\"sTotal\">0</b><span>應填人數</span></div><div class=\"stat\"><b id=\"sRate\">0%</b><span>完成率</span><div class=\"progress\"><i id=\"bar\"></i></div></div><div class=\"stat\"><b id=\"sNo\">0</b><span>不克參加</span></div></div><div class=\"card\"><h3>目前活動</h3><div id=\"activeSurveyInfo\" class=\"notice\"></div><div class=\"btns\"><button class=\"btn primary\" onclick=\"panel('surveyP',document.querySelector('[onclick*=surveyP]'))\">建立或編輯活動</button><button class=\"btn green\" onclick=\"panel('respP',document.querySelector('[onclick*=respP]'))\">查看投票結果</button></div></div></section>\r\n<section id=\"surveyP\" class=\"panel\"><div class=\"card\"><div class=\"surveyListHeaderV956\"><div><h3>活動列表</h3><p class=\"muted\">管理我發起、被分享及已結案的活動。</p></div><button class=\"btn primary\" type=\"button\" onclick=\"startNewSurvey()\">新增活動</button></div><div id=\"surveyEditor\" class=\"surveyEditor\"><div class=\"editorHead\"><div><h3 id=\"surveyFormHeading\">新增活動</h3><p id=\"surveyEditorContext\" class=\"editorContext\"></p></div><span id=\"surveyModeBadge\" class=\"modeBadge new\">新增模式</span></div><span id=\"surveyUnsaved\" class=\"unsavedMark\">● 尚未儲存的變更</span><div class=\"two\"><div class=\"field\"><label for=\"svTitle\">活動標題<span class=\"required\">*</span></label><input id=\"svTitle\" placeholder=\"115年第二次部門聚餐調查\"></div><div class=\"deadlineFields\"><div class=\"field\"><label for=\"svDeadline\">截止日期</label><input id=\"svDeadline\" type=\"date\"></div><div class=\"field\"><label for=\"svDeadlineTime\">截止時間</label><input id=\"svDeadlineTime\" type=\"time\" value=\"23:59\"></div></div></div><div class=\"field\"><label for=\"svDesc\">說明文字</label><textarea id=\"svDesc\" placeholder=\"感謝大家工作上的辛勞...\"></textarea></div><div class=\"field\"><label for=\"svInstructions\">前台填寫說明（選填）</label><textarea id=\"svInstructions\" maxlength=\"1000\" placeholder=\"例如：請勾選所有可以出席的日期；未勾選將視為無法出席。\"></textarea><small class=\"muted\">未填寫時，前台不會顯示「填寫說明」區塊。</small></div><div class=\"two\"><div class=\"field\"><label for=\"svStatus\">狀態</label><select id=\"svStatus\"><option value=\"open\">開放填寫</option><option value=\"closed\">已關閉</option><option value=\"draft\">草稿</option></select></div><div class=\"field\"><label for=\"svAllowEdit\">是否允許截止前修改</label><select id=\"svAllowEdit\"><option value=\"true\">允許</option><option value=\"false\">不允許</option></select></div></div><div class=\"field\"><label>參與部門<span class=\"required\">*</span></label><div id=\"targetDeptBox\" class=\"notice\"></div><small class=\"muted\">請至少選擇一個部門，避免活動誤開放給非本次調查對象。</small></div><div class=\"btns editorActions\"><button id=\"surveySaveBtn\" class=\"btn primary\" onclick=\"saveSurvey()\">建立活動</button><button class=\"btn\" onclick=\"cancelSurveyEdit()\">取消</button></div></div><div id=\"surveyTable\"></div></div></section>\n<section id=\"memP\" class=\"panel\"><div class=\"card\"><div class=\"memberToolbar\"><div><h3>人員設定</h3><p class=\"muted\">設定本活動誰可以填寫問卷，以及哪些人納入預算計算。這裡只影響目前活動，不會修改系統人員主檔。</p></div></div><input id=\"budgetPerPerson\" type=\"hidden\"><div id=\"memTable\"></div></div></section>\n<section id=\"sysMemP\" class=\"panel\"><div class=\"card\"><div class=\"memberToolbar\"><div><h3>人員管理</h3><p class=\"muted\">維護公司人員主檔及登入用 Google 帳號；活動管理者請到「人員設定」調整單一活動的填寫與預算資格。</p></div><div class=\"btns\"><button class=\"btn\" onclick=\"downloadMemberTemplate()\">下載標準範本</button><button class=\"btn\" onclick=\"chooseMemberImport()\">匯入 Excel</button><button class=\"btn green\" onclick=\"exportMembers()\">匯出名單</button><button class=\"btn primary\" onclick=\"startNewMember()\">＋ 新增人員</button><input id=\"memberImportInput\" class=\"fileInput\" type=\"file\" accept=\".xlsx,.xls,.csv\" onchange=\"importMembers(this.files[0]);this.value=''\" aria-label=\"匯入人員 Excel\"></div></div><div id=\"memberEditor\" class=\"memberEditor\"><div class=\"editorHead\"><h3 id=\"memberFormHeading\">新增人員</h3><span id=\"memberModeBadge\" class=\"modeBadge new\">新增模式</span></div><div class=\"memberFormGrid\"><div><label for=\"memDept\">部門<span class=\"required\">*</span></label><select id=\"memDept\"></select></div><div><label for=\"newMem\">姓名<span class=\"required\">*</span></label><input id=\"newMem\"></div><div><label for=\"newEmp\">員工編號<span class=\"required\">*</span></label><input id=\"newEmp\"></div><div><label for=\"memGoogle\">Google 帳號</label><input id=\"memGoogle\" type=\"email\" placeholder=\"name@gmail.com\"></div><div><label for=\"memCompanyEmailV957\">公司信箱</label><input id=\"memCompanyEmailV957\" type=\"email\" placeholder=\"name@mail.sinotech-eng.com\"></div><div><label for=\"memStatus\">狀態</label><select id=\"memStatus\"><option value=\"true\">啟用</option><option value=\"false\">停用</option></select></div></div><div class=\"btns\"><button id=\"memberSaveBtn\" class=\"btn primary\" onclick=\"saveMember()\">新增人員</button><button class=\"btn\" onclick=\"cancelMemberEdit()\">取消</button></div></div><div id=\"memberImportResult\" class=\"memberImportResult\" role=\"status\" aria-live=\"polite\"></div><div id=\"sysMemberTable\"></div></div></section>\r\n<section id=\"dateP\" class=\"panel\"><div class=\"card\"><div class=\"editorHead\"><div><h3 id=\"dateFormHeading\">新增日期</h3><p class=\"muted\">新增可選日期，或從下方列表選擇既有日期進行修改。</p></div><span id=\"dateModeBadge\" class=\"modeBadge new\">新增模式</span></div><div class=\"inline3\"><div><label>日期顯示文字</label><input id=\"newDate\" placeholder=\"8/15（五）晚上\"></div><div><label>排序</label><input id=\"newDateSort\" type=\"number\"></div><div class=\"btns compactActions\"><button id=\"dateSaveBtn\" class=\"btn primary\" onclick=\"saveDateV731Direct()\">新增日期</button><button id=\"dateCancelBtn\" class=\"btn\" onclick=\"cancelDateEdit()\" hidden>取消編輯</button></div></div><div id=\"dateTable\"></div></div></section>\r\n<section id=\"restP\" class=\"panel\"><div class=\"card\"><div class=\"editorHead\"><div><h3 id=\"restFormHeading\">新增餐廳</h3><p class=\"muted\">新增餐廳，或從下方列表選擇既有餐廳進行修改。</p></div><span id=\"restModeBadge\" class=\"modeBadge new\">新增模式</span></div><div class=\"two\"><div class=\"field\"><label>餐廳名稱</label><input id=\"newRest\"></div><div class=\"field\"><label>排序</label><input id=\"newRestSort\" type=\"number\"></div></div><div class=\"two\"><div class=\"field\"><label>地址</label><input id=\"newAddr\"></div><div class=\"field\"><label>Google Map</label><input id=\"newMap\" placeholder=\"https://...\"></div></div><div class=\"field\"><label>餐廳單價</label><input id=\"newPrice\" type=\"number\" min=\"0\" step=\"1\" placeholder=\"例如：1188\"></div><div id=\"restVarianceHint\" class=\"restVarianceHint\" hidden>價差改由「人員設定」中的每人預算與餐廳單價試算。</div><div class=\"field\"><label>類型</label><textarea id=\"newCuisine\" placeholder=\"例如：鐵板燒、火鍋、排餐、合菜，可空白\"></textarea></div><div class=\"btns\"><button id=\"restSaveBtn\" class=\"btn primary\" onclick=\"saveRestaurant()\">新增餐廳</button><button id=\"restCancelBtn\" class=\"btn\" onclick=\"cancelRestaurantEdit()\" hidden>取消編輯</button></div><div id=\"restTable\"></div></div></section>\n<section id=\"respP\" class=\"panel\"><div class=\"card\"><h3>投票結果</h3><div id=\"resultTables\"></div></div></section>\r\n<section id=\"costP\" class=\"panel\"><div class=\"card\"><h3>費用試算</h3><p class=\"muted\">決議前可選擇任一票選日期與餐廳試算；此頁只做評估，不會寫入或覆蓋最終決議。</p><div class=\"two\"><div class=\"field\"><label>試算日期</label><select id=\"costDate\" onchange=\"renderCostEstimate()\"></select></div><div class=\"field\"><label>試算餐廳</label><select id=\"costRest\" onchange=\"renderCostEstimate()\"></select></div></div><div id=\"costEstimatePreview\"></div></div></section>\n<section id=\"mailP\" class=\"panel\">\n  <div class=\"card mailComposerV957 mailComposerV968\">\n    <div class=\"mailComposerHeadV957\">\n      <div>\n        <h3>信件通知</h3>\n        <p class=\"muted\">依序選擇信件類型、正本收件者與主題，編輯內容後產生 EML 郵件草稿。</p>\n      </div>\n      <span id=\"mailRecipientCountV957\" class=\"countBadge\">0 人</span>\n    </div>\n    <div class=\"mailComposerGridV957\">\n      <div class=\"mailComposeFieldsV957\">\n        <div class=\"field\">\n          <label for=\"mailTypeV957\">信件類型</label>\n          <select id=\"mailTypeV957\" onchange=\"changeMailTypeV957(this.value)\">\n            <option value=\"invitation\">聚餐調查通知</option>\n            <option value=\"reminder\">逾期未填提醒</option>\n            <option value=\"result\">調查結果通知</option>\n            <option value=\"diningReminder\">聚餐行前提醒</option>\n          </select>\n        </div>\n        <div class=\"field mailRecipientFieldV968\">\n          <label>正本收件者</label>\n          <div class=\"mailRecipientSummaryBoxV968\">\n            <div>\n              <div id=\"mailRecipientSummaryV968\" class=\"mailRecipientSummaryV968\">尚未選擇收件者</div>\n              <small id=\"mailRecipientStatusV968\">公司信箱完整 0 人</small>\n            </div>\n            <button id=\"mailRecipientToggleV968\" class=\"btn\" type=\"button\" aria-expanded=\"false\" onclick=\"toggleMailRecipientsV968()\">選擇收件者</button>\n          </div>\n          <section id=\"mailRecipientPickerV968\" class=\"mailRecipientPickerV968\" hidden>\n            <div class=\"mailRecipientsHeadV957\">\n              <div>\n                <h4>選擇正本收件者</h4>\n                <p id=\"mailRecipientRuleV957\" class=\"muted\"></p>\n              </div>\n              <div class=\"btns\">\n                <button class=\"btn\" type=\"button\" onclick=\"setAllMailRecipientsV957(true)\">全選</button>\n                <button class=\"btn\" type=\"button\" onclick=\"setAllMailRecipientsV957(false)\">取消全選</button>\n              </div>\n            </div>\n            <div id=\"mailMissingEmailV957\"></div>\n            <div id=\"mailRecipientListV957\" class=\"mailRecipientListV957\"></div>\n            <p class=\"mailPrivacyNoteV957\">EML 使用正本收件者（To），收件者彼此可看見公司信箱。</p>\n          </section>\n        </div>\n        <div class=\"field\">\n          <label for=\"mailSubjectV957\">信件主旨</label>\n          <input id=\"mailSubjectV957\" maxlength=\"160\" oninput=\"updateMailPreviewV957()\">\n        </div>\n        <div id=\"mailThemeMountV968\"></div>\n        <div class=\"field\">\n          <label for=\"mailRichEditorV968\">信件內容</label>\n          <div class=\"mailEditorShellV968\">\n            <div class=\"mailEditorToolbarV968\" role=\"toolbar\" aria-label=\"信件內容格式工具\">\n              <button type=\"button\" data-mail-command=\"undo\" title=\"復原\" aria-label=\"復原\">↶</button>\n              <button type=\"button\" data-mail-command=\"redo\" title=\"重做\" aria-label=\"重做\">↷</button>\n              <span class=\"mailToolbarDividerV968\" aria-hidden=\"true\"></span>\n              <select id=\"mailFormatBlockV968\" aria-label=\"段落格式\" onchange=\"formatMailBlockV968(this.value)\">\n                <option value=\"div\">一般文字</option>\n                <option value=\"h2\">大標題</option>\n                <option value=\"h3\">小標題</option>\n              </select>\n              <button type=\"button\" data-mail-command=\"bold\" title=\"粗體\" aria-label=\"粗體\"><b>B</b></button>\n              <button type=\"button\" data-mail-command=\"italic\" title=\"斜體\" aria-label=\"斜體\"><i>I</i></button>\n              <button type=\"button\" data-mail-command=\"underline\" title=\"底線\" aria-label=\"底線\"><u>U</u></button>\n              <label class=\"mailColorControlV968\" title=\"文字顏色\">A<input id=\"mailTextColorV968\" type=\"color\" value=\"#173a63\" aria-label=\"文字顏色\"></label>\n              <label class=\"mailColorControlV968 mailHighlightControlV968\" title=\"醒目提示\">A<input id=\"mailHighlightColorV968\" type=\"color\" value=\"#fff2a8\" aria-label=\"醒目提示顏色\"></label>\n              <span class=\"mailToolbarDividerV968\" aria-hidden=\"true\"></span>\n              <button type=\"button\" data-mail-command=\"insertUnorderedList\" title=\"項目符號\" aria-label=\"項目符號\">•≡</button>\n              <button type=\"button\" data-mail-command=\"insertOrderedList\" title=\"編號清單\" aria-label=\"編號清單\">1≡</button>\n              <button type=\"button\" data-mail-command=\"justifyLeft\" title=\"靠左對齊\" aria-label=\"靠左對齊\">≡</button>\n              <button type=\"button\" data-mail-command=\"justifyCenter\" title=\"置中對齊\" aria-label=\"置中對齊\">≡</button>\n              <button type=\"button\" data-mail-command=\"createLink\" title=\"加入連結\" aria-label=\"加入連結\">🔗</button>\n              <button type=\"button\" data-mail-command=\"removeFormat\" title=\"清除格式\" aria-label=\"清除格式\">Tx</button>\n            </div>\n            <div id=\"mailRichEditorV968\" class=\"mailRichEditorV968\" contenteditable=\"true\" role=\"textbox\" aria-multiline=\"true\" spellcheck=\"true\"></div>\n          </div>\n          <textarea id=\"mailBodyV957\" class=\"mailBodyV957 mailBodySourceV968\" maxlength=\"8000\" hidden></textarea>\n          <div class=\"mailVariableHintV957\" aria-label=\"可插入的信件變數\">\n            <span>可用變數：</span>\n            <button type=\"button\" class=\"mailVariableButtonV969\" data-mail-variable=\"{{活動名稱}}\">{{活動名稱}}</button>\n            <button type=\"button\" class=\"mailVariableButtonV969\" data-mail-variable=\"{{填寫期限}}\">{{填寫期限}}</button>\n            <button type=\"button\" class=\"mailVariableButtonV969\" data-mail-variable=\"{{問卷連結}}\">{{問卷連結}}</button>\n            <button type=\"button\" class=\"mailVariableButtonV969\" data-mail-variable=\"{{最終日期}}\">{{最終日期}}</button>\n            <button type=\"button\" class=\"mailVariableButtonV969\" data-mail-variable=\"{{餐廳名稱}}\">{{餐廳名稱}}</button>\n            <button type=\"button\" class=\"mailVariableButtonV969\" data-mail-variable=\"{{餐廳地址}}\">{{餐廳地址}}</button>\n            <button type=\"button\" class=\"mailVariableButtonV969\" data-mail-variable=\"{{地圖連結}}\">{{地圖連結}}</button>\n          </div>\n        </div>\n        <div class=\"mailComposerActionsV957\">\n          <button class=\"btn\" type=\"button\" onclick=\"restoreMailTemplateV957()\">還原預設範本</button>\n          <button id=\"downloadEmlBtnV957\" class=\"btn primary\" type=\"button\" onclick=\"downloadMailEmlV957()\">產生 EML 草稿</button>\n        </div>\n      </div>\n      <aside class=\"mailPreviewCardV957\">\n        <div class=\"mailPreviewTitleV957\">\n          <h4>信件預覽</h4>\n          <span>實際寄送前仍可於郵件軟體修改</span>\n        </div>\n        <div id=\"mailPreviewV957\" class=\"mailPreviewV957\"></div>\n      </aside>\n    </div>\n  </div>\n</section>\n<section id=\"finalP\" class=\"panel\"><div class=\"card\"><div class=\"finalDecisionHeaderV1010\"><div><h3>結果鎖定 / 最終決議</h3><p class=\"muted\">選定最終日期後，系統會依同仁填寫的可參加日期自動整理出席名單。</p></div><div id=\"finalAttendanceAdjustmentActionV1010\" class=\"finalAttendanceAdjustmentActionV1010\"></div></div><div class=\"two\"><div class=\"field\"><label>最終日期</label><select id=\"finalDate\" onchange=\"renderFinalAttendancePreview()\"></select></div><div class=\"field\"><label>最終餐廳</label><select id=\"finalRest\" onchange=\"renderFinalAttendancePreview()\"></select></div></div><div class=\"field\"><label>決議說明</label><textarea id=\"finalNote\"></textarea></div><div class=\"field\"><label for=\"finalLock\">前台顯示狀態</label><select id=\"finalLock\"><option value=\"false\">尚未決定</option><option value=\"true\">已決定並顯示於前台</option></select></div><div id=\"finalHomeAnnouncementBlock\" class=\"field homeAnnouncementSelectFieldV944\"><label for=\"finalHomeAnnouncement\">登入首頁公告</label><div class=\"homeAnnouncementSelectRowV944\"><select id=\"finalHomeAnnouncement\" aria-describedby=\"finalHomeAnnouncementHint\"><option value=\"false\">不顯示於登入首頁</option><option value=\"true\">顯示於登入首頁</option></select><button id=\"homeAnnouncementSettingsShortcut\" class=\"btn homeAnnouncementSettingsShortcut\" type=\"button\" onclick=\"openHomeAnnouncementSettings()\" hidden>前往功能設定</button></div><p id=\"finalHomeAnnouncementHint\" class=\"muted\">僅公開活動名稱、最終日期、餐廳與地圖。</p></div><div class=\"btns\"><button class=\"btn primary\" onclick=\"saveFinal()\">儲存最終決議</button><button class=\"btn green\" onclick=\"exportExcel()\">匯出 Excel</button></div><div id=\"finalAttendancePreview\"></div></div></section>\n<section id=\"accessP\" class=\"panel\"><div class=\"card\"><h3>活動權限管理</h3><p class=\"muted\">針對目前選取的活動分享管理或檢視權限。活動管理者只能分享自己被指派管理的活動；分享後，該活動會顯示於對方的「被分享的活動」。</p><div class=\"accessForm\"><div><label for=\"managerEmail\">分享成員</label><select id=\"managerEmail\"><option value=\"\">請選擇成員</option></select><datalist id=\"memberGoogleOptions\"></datalist><small class=\"muted\">Google 帳號係同仁部門行事曆使用之帳號；如帳號異動，請洽系統管理員修正後方可登入。</small></div><div><label for=\"managerRole\">權限</label><select id=\"managerRole\"><option value=\"manager\">活動管理者</option><option value=\"viewer\">結果檢視者</option></select></div><button class=\"btn primary\" onclick=\"saveSurveyManager()\">新增／更新權限</button></div><div id=\"managerTable\"></div></div></section>\n<section id=\"frontProtectP\" class=\"panel\"><div class=\"card\"><h3>前台防護</h3><p class=\"muted\">設定整個前台的防誤操作行為。這不是資安防護，只能降低一般使用者誤開右鍵、原始碼或開發者工具的便利性。</p><div id=\"frontProtectionSettingsBox\"></div></div></section>\n<section id=\"featureSettingsP\" class=\"panel\"><div class=\"card featureSettingsPageV943\"><h3>功能設定</h3><p class=\"muted\">控制全系統共用功能；停用功能不會刪除既有資料。</p><div class=\"featureSettingsGridV943\"><section class=\"featureSettingCardV943\" aria-labelledby=\"chatSettingTitleV943\"><div class=\"featureSettingRowV915\"><div><strong id=\"chatSettingTitleV943\">即時聊天室</strong><p class=\"muted\">提供一對一、多人聊天室、固定貼圖與已讀狀態。</p></div><label class=\"switchV915\"><input id=\"chatEnabledV915\" type=\"checkbox\"><span aria-hidden=\"true\"></span><b id=\"chatEnabledTextV915\">停用</b></label></div><footer class=\"featureSettingFooterV943\"><span id=\"chatSettingSaveStateV943\" class=\"featureSettingSaveStateV943\" aria-live=\"polite\"></span><button id=\"saveChatSettingV915\" class=\"btn blue\" type=\"button\" onclick=\"saveChatSettingV915()\">儲存設定</button></footer></section><section class=\"featureSettingCardV943 homeAnnouncementSetting\" aria-labelledby=\"homeAnnouncementTitleV943\"><div class=\"homeAnnouncementSettingHead\"><div><strong id=\"homeAnnouncementTitleV943\">登入首頁聚餐公告</strong><p class=\"muted\">選擇登入頁左側的公告樣式；暫停使用時保留各活動的發布設定。</p></div><span id=\"homeAnnouncementModeStatus\" class=\"badge gray\">暫停使用</span></div><div class=\"homeAnnouncementModeChoices\" role=\"radiogroup\" aria-label=\"登入首頁聚餐公告顯示方式\"><label><input type=\"radio\" name=\"homeAnnouncementMode\" value=\"cards\"><span><b>卡片式</b><small>適合一至三場近期聚餐，重點清楚醒目。</small></span></label><label><input type=\"radio\" name=\"homeAnnouncementMode\" value=\"list\"><span><b>清單表格式</b><small>日期、活動、餐廳與地圖單列對齊。</small></span></label><label><input type=\"radio\" name=\"homeAnnouncementMode\" value=\"paused\" checked><span><b>暫停使用公告</b><small>登入頁維持原本插圖，公告資料不會刪除。</small></span></label></div><p id=\"homeAnnouncementPauseHintV943\" class=\"homeAnnouncementPauseHintV943\" hidden>各活動原本的公告設定將保留，登入首頁暫不顯示公告。</p><footer class=\"featureSettingFooterV943\"><span id=\"homeAnnouncementSaveStateV943\" class=\"featureSettingSaveStateV943\" aria-live=\"polite\"></span><button id=\"saveHomeAnnouncementSetting\" class=\"btn blue\" type=\"button\" onclick=\"saveHomeAnnouncementSetting()\">儲存設定</button></footer></section></div></div></section>\n</main></div></div>\n<div id=\"memberImportModeMask\" class=\"modalMask memberImportModalMask\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"memberImportModeTitle\">\n  <section class=\"modal memberImportModeDialog\">\n    <div class=\"memberImportModalHead\"><div><h2 id=\"memberImportModeTitle\">選擇人員匯入方式</h2><p>請依這份 Excel 的範圍選擇，避免把未列入的同仁誤判為離職。</p></div><button class=\"memberImportClose\" type=\"button\" onclick=\"closeMemberImportMode()\" aria-label=\"關閉\">×</button></div>\n    <div class=\"memberImportModeChoices\">\n      <label class=\"memberImportModeChoice\"><input type=\"radio\" name=\"memberImportMode\" value=\"partial\" checked><span><b>部分名單更新</b><small>只新增或更新 Excel 內的人員，不檢查其他既有人員。</small></span></label>\n      <label class=\"memberImportModeChoice\"><input type=\"radio\" name=\"memberImportMode\" value=\"full\"><span><b>完整名單核對</b><small>比對整份公司名單，列出本次未出現的啟用人員，再由您決定是否停用。</small></span></label>\n    </div>\n    <div class=\"memberImportModalActions\"><button class=\"btn\" type=\"button\" onclick=\"closeMemberImportMode()\">取消</button><button class=\"btn primary\" type=\"button\" onclick=\"continueMemberImport()\">選擇 Excel</button></div>\n  </section>\n</div>\n<div id=\"memberImportReviewMask\" class=\"modalMask memberImportModalMask\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"memberImportReviewTitle\">\n  <section class=\"modal memberImportReviewDialog\">\n    <div class=\"memberImportModalHead\"><div><h2 id=\"memberImportReviewTitle\">確認人員名單差異</h2><p id=\"memberImportReviewCaption\"></p></div><button class=\"memberImportClose\" type=\"button\" onclick=\"closeMemberImportReview()\" aria-label=\"關閉\">×</button></div>\n    <div id=\"memberImportReviewBody\" class=\"memberImportReviewBody\"></div>\n    <div class=\"memberImportModalActions\"><button class=\"btn\" type=\"button\" onclick=\"closeMemberImportReview()\">取消</button><button id=\"confirmMemberImportBtn\" class=\"btn primary\" type=\"button\" onclick=\"confirmMemberImport()\">匯入名單</button></div>\n  </section>\n</div>";})();